INSERT INTO communities(id,name,description,city_id,category,verified,status) VALUES ('53496a58-368f-443e-9d4b-8ce36e14fa52','Warsaw Morning Run','Easy dawn miles along the Vistula. Every pace welcome, coffee after.',(SELECT id FROM cities WHERE country_code='PL' AND name='Warsaw'),'running',true,'active') ON CONFLICT DO NOTHING;
INSERT INTO communities(id,name,description,city_id,category,verified,status) VALUES ('f41d51a7-3961-4e96-a659-724caa5f5a83','London Bridges Runners','Tempo runs across the city’s bridges. Social, friendly, a little competitive.',(SELECT id FROM cities WHERE country_code='GB' AND name='London'),'running',true,'active') ON CONFLICT DO NOTHING;
INSERT INTO communities(id,name,description,city_id,category,verified,status) VALUES ('db3d78af-dda7-4910-a21c-6f8d6e9d187a','Beirut Corniche Crew','Seaside runs on the Corniche and good company at sunrise.',(SELECT id FROM cities WHERE country_code='LB' AND name='Beirut'),'running',true,'active') ON CONFLICT DO NOTHING;
